function onResponse (headers) {
  const stream = this
  const state = stream[kRequestStreamState]
  const { request } = state

  stream.off('response', onResponse)

  const statusCode = headers[HTTP2_HEADER_STATUS]
  delete headers[HTTP2_HEADER_STATUS]
