'use strict'

// Regression test for https://github.com/nodejs/undici/issues/5404
//
// HTTP/2 streams complete out of order. The h2 completion path used to do:
//
//   client[kQueue][client[kRunningIdx]++] = null
//
// which assumes the request that finished is the one at kRunningIdx. When a
// later stream completed first, the slot of a *still running* request was
// cleared and the completed request stayed inside the running section. The
// destroy/error paths then lost the running request (its promise never
// settled) and walked over null queue entries.

const { test, after } = require('node:test')
const assert = require('node:assert')
const { createSecureServer } = require('node:http2')
const { once } = require('node:events')
const pem = require('@metcoder95/https-pem')

const { Client } = require('..')
const { kQueue, kRunningIdx, kPendingIdx, kRunning } = require('../lib/core/symbols')

// The requests still considered running by the client, in queue order.
function runningRequests (client) {
  return client[kQueue].slice(client[kRunningIdx], client[kPendingIdx])
}

test('h2 out-of-order completion keeps the other running requests queued', async () => {
  const server = createSecureServer(await pem.generate({ opts: { keySize: 2048 } }))

  const slowStreams = []
  server.on('stream', (stream, headers) => {
    if (headers[':path'] === '/slow') {
      // Keep the first stream open until the second one has completed.
      slowStreams.push(stream)
      return
    }

    stream.respond({ ':status': 200 })
    stream.end('fast')
  })

  await once(server.listen(0), 'listening')
  after(() => server.close())

  const client = new Client(`https://localhost:${server.address().port}`, {
    connect: { rejectUnauthorized: false },
    allowH2: true
  })
  after(() => client.close())

  const slow = client.request({ path: '/slow', method: 'GET' })
    .then(async res => {
      await res.body.text()
      return res.statusCode
    })

  // Dispatch both requests on the same session before either completes.
  const fast = await client.request({ path: '/fast', method: 'GET' })
  assert.strictEqual(await fast.body.text(), 'fast')

  // `/fast` was dispatched second but completed first. It must be gone from
  // the queue, and `/slow` must still be accounted for as running.
  const running = runningRequests(client)
  assert.deepStrictEqual(running.map(request => request?.path), ['/slow'])
  assert.strictEqual(client[kRunning], 1)
  assert.ok(
    client[kRunningIdx] <= client[kPendingIdx],
    `kRunningIdx (${client[kRunningIdx]}) must not pass kPendingIdx (${client[kPendingIdx]})`
  )

  for (const stream of slowStreams) {
    stream.respond({ ':status': 200 })
    stream.end('slow')
  }

  assert.strictEqual(await slow, 200)
  assert.strictEqual(client[kRunning], 0)
})

test('h2 destroy after an out-of-order completion rejects the running request', async () => {
  const server = createSecureServer(await pem.generate({ opts: { keySize: 2048 } }))

  server.on('stream', (stream, headers) => {
    if (headers[':path'] === '/slow') {
      return
    }

    stream.respond({ ':status': 200 })
    stream.end('fast')
  })

  await once(server.listen(0), 'listening')
  after(() => server.close())

  const client = new Client(`https://localhost:${server.address().port}`, {
    connect: { rejectUnauthorized: false },
    allowH2: true
  })

  const clientErrors = []
  client.on('error', err => clientErrors.push(err))

  // The still-running `/slow` request must be errored by the destroy, not
  // dropped on the floor because its queue slot was cleared by `/fast`.
  // The expectation is attached upfront so the rejection is never orphaned.
  const slowRejected = assert.rejects(
    client.request({ path: '/slow', method: 'GET' }),
    /destroyed while running/
  )

  const fast = await client.request({ path: '/fast', method: 'GET' })
  assert.strictEqual(await fast.body.text(), 'fast')

  await client.destroy(new Error('destroyed while running'))

  await slowRejected
  assert.deepStrictEqual(clientErrors, [])
})

