test('destroying a client skips stale null queue entries', async () => {
  // We never connect; only the initialized internal state is needed.
  const client = new Client('https://localhost:1', {
    connect: { rejectUnauthorized: false },
    allowH2: true
  })

  const clientErrors = []
  client.on('error', err => clientErrors.push(err))

  // The slot of an already finalized request, left in the pending section by
  // a kPendingIdx reset (e.g. onHttp2SocketClose).
  client[kQueue].push(null)
  client[kRunningIdx] = 0
  client[kPendingIdx] = 0

  await client.destroy(new Error('boom'))

  // Without the null guard the cleanup loop dereferences the empty slot and
  // the resulting TypeError is re-emitted as a client 'error'.
  assert.deepStrictEqual(clientErrors, [])
})

